    #[inline(always)]
    pub fn disable(&mut self) -> (delay: Tracked<Mim::delay>)
        requires !old(self).is_empty(),
            old(self).wf(),
        ensures
            final(self).wf(),
            final(self).is_empty(),
            final(self).instance == old(self).instance,
